		/* strnlen() is a GNU extension. */
		#if !HAVE_STRNLEN
static size_t strnlen(const char *s, size_t n)
{
	const char *p = (const char *)memchr(s, 0, n);
	return p ? p - s : n;
}
		#endif /* !HAVE_STRNLEN */
